result.text:
  .sidebar {
    width: auto;
    flex: 0 0 auto;
    height: auto;
    position: sticky;
    top: 0;
    z-index: 20;
    flex-direction: row;
    align-items: center;
    gap: 10px;
    padding: 9px 12px;
    border-right: none;
    border-bottom: 1px solid var(--line);
    overflow-x: auto;
  }
  .brand { padding: 0; flex: 0 0 auto; }
  .brand-text { display: none; }
  .brand-mark { width: auto; height: 30px; max-width: 120px; }
  .brand-mark img { width: auto; height: 30px; max-height: 30px; }

  .nav { flex-direction: row; gap: 4px; }
  .nav a { padding: 7px 10px; font-size: 13.5px; }
  .nav a svg { width: 16px; height: 16px; }
  .sidebar-foot { display: none; }

  .topbar { padding: 14px 18px; }
  .topbar-titles h1 { font-size: 18px; }
  .topbar-titles p { font-size: 12px; }
  #view { padding: 18px 18px 80px; }

  .kpis { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 10px; }
  .kpi .kpi-value { font-size: 22px; }
  .howto { grid-template-columns: minmax(0, 1fr); }
  .form-grid { grid-template-columns: minmax(0, 1fr); }
  .form-grid .span-2 { grid-column: span 1; }
  .modal { padding: 12px 10px; }
  .modal-body, .modal-head, .modal-foot { padding-left: 16px; padding-right: 16px; }
  .toasts { right: 12px; bottom: 12px; left: 12px; max-width: none; }
}

@media (max-width: 560px) {
  .nav a span:not(.nav-count) { display: none; }
  .nav a { padding: 8px; }
  .topbar-actions .btn span { display: none; }
  .topbar-actions .btn { padding: 9px; }
  .supplier-grid { grid-template-columns: minmax(0, 1fr); }
  .kpi .kpi-value { font-size: 20px; }
  .filters { gap: 8px; }
  .filters .search { flex: 1 1 100%; }
}

/* ---------- Espera mientras se abre la base de datos ------------------- */

.spinner.big {
  width: 26px; height: 26px;
  border-width: 2.5px;
}

/* ---------- Panel de la base de datos ---------------------------------- */

.db-stats {
  display: flex; flex-wrap: wrap; gap: 8px;
  list-style: none; margin: 0; padding: 0;
}
.db-stats li {
  padding: 6px 11px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  font-size: 12.5px;
  color: var(--ink-2);
}
.db-stats strong { color: var(--ink-1); }

/* ---------- Cámara ----------------------------------------------------- */

.camera-overlay {
  position: fixed; inset: 0;
  z-index: 90;
  display: flex; flex-direction: column;
  background: #0b0f0e;
  color: #f3f5f4;
  animation: fade .15s ease-out;
}

.camera-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
}
.camera-head strong { display: block; font-size: 15px; font-weight: 650; }
.camera-head span { display: block; font-size: 12px; color: #9fb0ac; margin-top: 2px; }
.camera-overlay .icon-btn {
  color: #dfe6e4;
  background: rgba(255, 255, 255, .08);
  border-color: transparent;
}
.camera-overlay .icon-btn:hover { background: rgba(255, 255, 255, .16); }

.camera-stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  background: #000;
}
.camera-stage video {
  width: 100%; height: 100%;
  object-fit: contain;
  display: block;
}
.camera-flash {
  position: absolute; inset: 0;
  background: #fff;
  opacity: 0;
  pointer-events: none;
}
.camera-flash.on { animation: camflash .28s ease-out; }
@keyframes camflash { from { opacity: .85; } to { opacity: 0; } }
